import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>1:1, 4:3, 16:9... Bu sayılar, görselin biçimini anlatır. Doğru oran, fotoğrafın hedefte tam görünmesini sağlar.</p>\n<p>Yanlış oran, fotoğrafın otomatik kırpılmasına yol açar. Önemli ayrıntı kesilir ve görsel bozulur.</p>\n<p>Bu yazı, en yaygın oranları, her birinin nerede kullanıldığını ve oran ile çözünürlük arasındaki farkı anlatıyor.</p>\n<h2 id=\"what-is-an-aspect-ratio\">Oran nedir?</h2>\n<p>Oran, genişliğin yüksekliğe oranıdır. 16:9, görselin 16 birim genişliğinde ve 9 birim yüksekliğinde olduğunu söyler.</p>\n<p>Oran, boyuttan bağımsızdır. 1600x900 ve 1920x1080 görsellerin ikisi de 16:9 oranındadır.</p>\n<p>Oran, biçimi belirler; çözünürlük, ayrıntıyı belirler. İki kavram karıştırılmamalıdır.</p>\n<h2 id=\"ratio-1-1\">1:1: kare</h2>\n<p>1:1, genişlik ve yüksekliğin eşit olduğu kare biçimdir. Profil fotoğrafları kare ister.</p>\n<p>Kare, simetrik konular için idealdir. Yüz ve ürün, karede dengeli görünür.</p>\n<p>Kare kırpma, yatay fotoğraftan çok şey atar. Konuyu merkeze alın; kenarlar kesilir.</p>\n<h2 id=\"ratio-4-3\">4:3: klasik fotoğraf biçimi</h2>\n<p>4:3, eski televizyon ve fotoğraf makinesi standardıdır. Hâlâ birçok platformda kullanılır.</p>\n<p>4:3, kareye yakın ama biraz geniştir. Portre ve manzara için dengeli bir biçimdir.</p>\n<p>Baskıda 4:3 yaygındır. 10x15 baskı, 3:2 ister ama 4:3 de kabul edilir.</p>\n<h2 id=\"ratio-3-2\">3:2: kamera standardı</h2>\n<p>3:2, fotoğraf makinelerinin standart oranıdır. 35 mm filmden gelir.</p>\n<p>3:2, manzara ve sokak fotoğrafı için idealdir. Geniş ama abartılı değildir.</p>\n<p>Baskıda 3:2 yaygındır. 10x15 baskı tam olarak 3:2 oranındadır.</p>\n<h2 id=\"ratio-16-9\">16:9: geniş ekran</h2>\n<p>16:9, modern ekranların oranıdır. Televizyon, video ve kapak görselleri 16:9 ister.</p>\n<p>16:9, manzara için idealdir. Geniş ufuklar ve kalabalık sahneler bu oranda iyi görünür.</p>\n<p>Portre için 16:9 yanlıştır. Dikey konular, geniş çerçevede kaybolur.</p>\n<h2 id=\"ratio-4-5-and-9-16\">4:5 ve 9:16: dikey biçimler</h2>\n<p>4:5, dikey gönderiler için kullanılır. Instagram akışında dikey görseller daha çok yer kaplar.</p>\n<p>9:16, hikâye ve kısa video biçimidir. Telefon ekranını tam doldurur.</p>\n<p>Dikey biçimler, portre ve ürün için idealdir. Konu, çerçeveyi doldurur.</p>\n<h2 id=\"custom-ratios\">Özel oranlar: hiçbir ön ayar uymadığında</h2>\n<p>Bazen hiçbir ön ayar uymaz. Afiş ya da özel baskı, farklı oran ister.</p>\n<p>Serbest kırpma kullanın. Seçim kutusunu istediğiniz biçime sürükleyin.</p>\n<p>Özel oranı not edin. Ekip, aynı oranı kullanmalıdır.</p>\n<h2 id=\"ratio-vs-resolution\">Oran ve çözünürlük: iki farklı şey</h2>\n<p>Oran biçimi, çözünürlük ayrıntıyı belirler. 16:9 oranındaki bir görsel, 1600x900 ya da 1920x1080 olabilir.</p>\n<p>Oranı değiştirmek, biçimi değiştirir. Çözünürlüğü değiştirmek, piksel sayısını değiştirir.</p>\n<p>İkisini karıştırmayın. Küçük ama doğru oranlı görsel, büyük ama yanlış oranlı görselden iyidir.</p>\n<h2 id=\"ratio-mistakes\">Yanlış orandan doğan hatalar</h2>\n<p>En yaygın hata, platform oranını öğrenmeden kırpmaktır. Platform, görseli otomatik kırpar ve önemli ayrıntı kesilir.</p>\n<p>Bir başka hata, kareye zorlamaktır. Grup fotoğrafı kareye zorlanmamalıdır; geniş oran daha doğrudur.</p>\n<p>Üçüncü hata, oranı sonradan değiştirmektir. Yanlış oranla kırpılan görsel düzeltilemez; yeniden kırpılmalıdır.</p>\n<h2 id=\"ratio-for-print\">Baskı için oranlar</h2>\n<p>Baskıda oran, kâğıt boyutuna uymalıdır. 10x15 baskı 3:2, 13x18 baskı 4:3 ister.</p>\n<p>Yanlış oran, baskıda beyaz kenar ya da kırpma demektir. Baskı merkezine sormaktan çekinmeyin.</p>\n<p>Baskıda çözünürlük çok önemlidir. 300 DPI hedefleyin; küçük kırpma baskıda bulanık çıkar.</p>\n<h2 id=\"ratio-workflow\">Oran seçmek için bir akış</h2>\n<p>Önce hedefi belirleyin. Profil mi, afiş mi, baskı mı? Hedef oranı belirler.</p>\n<p>Sonra platform kurallarını öğrenin. Her platform kendi oranını ister.</p>\n<p>Son olarak kırpın ve kontrol edin. Önizlemede konunun tam göründüğünü doğrulayın.</p>\n<h2 id=\"ratio-cheat-sheet\">Hızlı oran kılavuzu</h2>\n<p>Profil fotoğrafı: 1:1. Kapak görseli: 16:9. Hikâye: 9:16. Dikey gönderi: 4:5.</p>\n<p>Baskı 10x15: 3:2. Baskı 13x18: 4:3. Video küçük resmi: 16:9.</p>\n<p>Bu listeyi kaydedin. Her kırpmada yeniden aramak zaman kaybıdır.</p>\n<h2 id=\"ratio-for-video-thumbnails\">Video küçük resimleri için oranlar</h2>\n<p>Video küçük resimleri 16:9 ister. YouTube ve benzeri platformlar bu oranı kullanır.</p>\n<p>Küçük resimde konu merkeze alınmalıdır. Kenarlar, platformda kesilebilir.</p>\n<p>Yazı büyük olmalıdır. Küçük resim, küçük ekranda okunmalıdır.</p>\n<h2 id=\"ratio-for-ecommerce\">E-ticaret ve ürün listeleri için oranlar</h2>\n<p>Ürün listelerinde tutarlılık önemlidir. Tüm ürün görselleri aynı oranda olmalıdır.</p>\n<p>1:1, ürün listeleri için yaygındır. Kare, mağazada düzenli görünür.</p>\n<p>Ürün fotoğraflarında ürünü merkeze alın. Arka plan sade olmalı.</p>\n<h2 id=\"ratio-and-composition\">Oran ve kompozisyon: biçim duyguyu nasıl değiştirir?</h2>\n<p>Geniş oran, ferahlık hissi verir. Manzara fotoğrafları geniş oranda nefes alır.</p>\n<p>Kare oran, denge hissi verir. Portre ve ürün, karede sakin görünür.</p>\n<p>Dikey oran, yükseklik hissi verir. Binalar ve portreler dikeyde güçlüdür.</p>\n<h2 id=\"ratio-changes-over-time\">Oranlar değişir: platformlara ayak uydurmak</h2>\n<p>Platformlar oran kurallarını değiştirir. Instagram, yıllar içinde kareden dikeye geçti.</p>\n<p>Kuralları düzenli kontrol edin. Eski oranla kırpılan görsel, platformda yanlış görünür.</p>\n<p>Orijinalleri saklayın. Oran değişirse orijinalden yeniden kırpabilirsiniz.</p>\n<p>Özetle: oran biçimi, çözünürlük ayrıntıyı belirler. Adımlar için <a href=\"/tr/blog/gorsel-nasil-kirpilir\">Görsel kırpma nasıl yapılır</a> yazısına bakın; kılavuzun tamamı <a href=\"/tr/blog/gorsel-kirp-rehberi\">Görsel kırpıcı kılavuzunda</a>. Boyut için <a href=\"/tr/gorsel-boyutlandir\">görsel boyutlandırıcı</a>, kırpma için <a href=\"/tr/gorsel-kirp\">görsel kırpıcı</a> hazırdır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Kırpmada 1:1 ne demek?","answer":"1:1, genişlik ve yüksekliğin eşit olduğu kare biçim demektir. Profil fotoğrafları kare ister. Kare, simetrik konular için idealdir; yüz ve ürün karede dengeli görünür."},{"question":"YouTube küçük resmi için hangi oranı kullanmalıyım?","answer":"16:9 kullanın. YouTube ve benzeri platformlar bu oranı ister. Küçük resimde konuyu merkeze alın ve yazıyı büyük tutun; küçük resim küçük ekranda okunmalıdır."},{"question":"Fotoğrafı, kameramın çekmediği bir orana kırpabilir miyim?","answer":"Evet. Kırpma, oranı değiştirir; kameranın oranı önemli değildir. Yatay fotoğrafı kareye, kare fotoğrafı dikeye çevirebilirsiniz. Ancak dar kırpma, piksel kaybı demektir."},{"question":"Fotoğraf bastırmak için hangi oranı kullanmalıyım?","answer":"Kâğıt boyutuna uyun: 10x15 baskı 3:2, 13x18 baskı 4:3 ister. Yanlış oran, baskıda beyaz kenar ya da kırpma demektir. Baskı merkezine sormaktan çekinmeyin."},{"question":"Instagram fotoğrafımı yükledikten sonra neden kırpıyor?","answer":"Çünkü yüklediğiniz oran, platformun oranıyla uymuyor. Instagram, görseli kendi oranına zorlar ve kenarları keser. Yüklemeden önce platformun istediği orana kırpın; önemli öğeleri merkeze koyun."},{"question":"Oran ile çözünürlük arasındaki fark nedir?","answer":"Oran biçimi, çözünürlük ayrıntıyı belirler. 16:9 oranındaki bir görsel 1600x900 ya da 1920x1080 olabilir; ikisi de aynı biçimdedir ama farklı ayrıntıdadır. Oranı değiştirmek biçimi, çözünürlüğü değiştirmek piksel sayısını değiştirir."}];
